package core

import (
	"encoding/hex"
	"enkv.sh/core/contract"
	"testing"
)

// full_only: false
func TestPublicQueryCanonicalFramesAndOperationIdentitiesMatchIndependentVectors(t *testing.T) {
	// Expected frames and hashes were derived with Python struct and hashlib.
	for _, vector := range []struct {
		operation            string
		semantic             uint16
		selector             byte
		observed             bool
		frame, query, result string
	}{
		{"receipt-list", 16, 0, false,
			"",
			"06444aadb6ee2e8bf2b5957642234cbcd01eaeda615409b74763e4d81c7f70a7", "ecf7e3c36bdc083987de81f59509e983b56404d8a10aed181322fb67c9e2017b"},
		{"receipt-list", 16, 0, true,
			"",
			"b5eebc4ca789a02352574059e246a6cf15543a50cee63529b498001924e63c63", "d4d1311de968d326da821427b9baaffee924ae5d2b80658df0a53eb4bef16714"},
		{"receipt-detail", 16, 15, false,
			"",
			"1e7035082f82b9e2323187f05ff3012559f1fc4e72a47d78c74e90d74e125a81", "1a4a22ebb6f9537cec6c028b0270e899ba06919704ea53a081568f95df01e5ab"},
		{"receipt-detail", 16, 15, true,
			"",
			"f31a9a1a0dc163b9b48c16ab9c8a3061bdc46fff29864ba5027b09197e40943c", "1a3e53967e4fffedc45c56786ea5467924767b3546e67ab7ce74d011a65b7b16"},
		{"inspect", 15, 0, false,
			"",
			"aa06daba9a71f16d72504b9a48630703dfa559667a868152fe0186dd8e8ae5ff", "af625675030f32ad72d875378fbed1fa704620d8fd08e560b60b82db24db39f4"},
		{"inspect", 15, 0, true,
			"",
			"fc90a9a341bc726c4faaa5ea5b47a788c99e91caa88a0954c316c4222b07de01", "569a6ee13f5d428d7af26385b52d2bdb4851d8a572fd7c13449d37e1e99f0c71"},
		{"inspect-recipient", 15, 15, false,
			"",
			"8535f926edca03c749d500d6743289ce5b55c067c6b9b7325a85d879db508c0d", "a4046a944d2d1bb948e1aa5fc4848c68d93ccdd9a036c92cedfa06ea22def5ac"},
		{"inspect-recipient", 15, 15, true,
			"",
			"435581d96ef25220dcb3c4a81423bafdbdecd056e3663dc61f017eb23bd925ca", "32b3f67484845b14805fc1998f3a0d2eb36012fa8a126405ec9503046c443e07"},
	} {
		q := PublicQueryBasis{Schema: "QueryRequestIdentity/v1", Operation: vector.operation, SemanticOperation: vector.semantic,
			ExpectedDomain: contract.ID{1}, StoreID: contract.ID{2}, CoordinateID: contract.ID{3}, NonBodyID: contract.ID{4}, StoreDescriptorDigest: contract.ID{5}, PublicBasisDigest: contract.ID{6},
			SourcePins: AdministrativeSourcePins{FileID: contract.ID{11}, Format: 1, EditableDigest: contract.ID{12}, GeneratedDigest: contract.ID{13}, EditableLength: 123, GeneratedLength: 456, HasGenerated: true}, RequestNonce: contract.ID{14}}
		if vector.observed {
			q.Observation = &PublicObservation{contract.ID{1}, contract.ID{16}, contract.ID{17}, contract.ID{18}}
		}
		selector := contract.ID{vector.selector}
		frame, ok := q.identityBytes(selector)
		if !ok || hex.EncodeToString(frame) != vector.frame {
			t.Fatal("canonical query bytes differ", vector.operation, vector.observed)
		}
		query, ok := q.digest(selector)
		if !ok || hex.EncodeToString(query[:]) != vector.query {
			t.Fatal("canonical query identity differs", vector.operation, vector.observed)
		}
		operation := publicQueryOperationID(query)
		if hex.EncodeToString(operation[:]) != vector.result {
			t.Fatal("query operation identity differs", vector.operation, vector.observed)
		}
	}
}
